// NushiServiceHandler is an implementation of the nushi.v1.NushiService service.
type NushiServiceHandler interface {
	Ping(context.Context, *connect.Request[v1.PingRequest]) (*connect.Response[v1.PingResponse], error)
	// Stops the daemon once no chat has a turn running or waiting on the
	// user, nothing is queued and no terminal runs a command; prompts are
	// refused from then on (Unavailable), to be sent again to the new one.
	// The Mac's app asks while it bundles a newer daemon than the one
	// running, again every few seconds (an ask lapses after 15 s, so an app
	// that quit leaves the daemon running), and starts the new one once
	// this one has gone. Not on a device's channel. API 77.
	RestartWhenIdle(context.Context, *connect.Request[v1.RestartWhenIdleRequest]) (*connect.Response[v1.RestartWhenIdleResponse], error)
	// Lists every stored chat.
	ListChats(context.Context, *connect.Request[v1.ListChatsRequest]) (*connect.Response[v1.ListChatsResponse], error)
	// Returns everything a chat's events have built so far, to pick it up
	// after (re)connecting.
	GetChat(context.Context, *connect.Request[v1.GetChatRequest]) (*connect.Response[v1.GetChatResponse], error)
	// A chat's items before one of them, a page at a time: for a client that
	// took only the recent part (GetChatRequest.recent), as it scrolls up.
	GetChatItems(context.Context, *connect.Request[v1.GetChatItemsRequest]) (*connect.Response[v1.GetChatItemsResponse], error)
	// Starts an agent in a folder and opens a chat with it.
	StartChat(context.Context, *connect.Request[v1.StartChatRequest]) (*connect.Response[v1.StartChatResponse], error)
	// Lists the agents chats can run, the default first, each as found on
	// this Mac now: its CLI on the login shell's PATH and its version. Each
	// CLI is only asked what it is, with file writes and the network denied.
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	// Sets up an agent's adapter (Agent.adapter): installs it into Nushi's
	// data folder from the lockfile Nushi pins, or updates it to the pinned
	// version. The agent's awake chats sleep just before the new one
	// replaces the old. Returns once it's done (5 minutes at most).
	SetUpAgent(context.Context, *connect.Request[v1.SetUpAgentRequest]) (*connect.Response[v1.SetUpAgentResponse], error)
	// Removes an agent's adapter; its awake chats sleep first.
	RemoveAgent(context.Context, *connect.Request[v1.RemoveAgentRequest]) (*connect.Response[v1.RemoveAgentResponse], error)
	// Lists an agent's sessions in a folder that aren't chats (started in a
	// terminal, say), newest first, a page at a time. It starts the agent to
	// ask (ACP session/list).
	ListAgentSessions(context.Context, *connect.Request[v1.ListAgentSessionsRequest]) (*connect.Response[v1.ListAgentSessionsResponse], error)
	// Opens one of them as a chat in the folder: the agent replays it
	// (session/load); nothing is copied. For a session that is a chat
	// already, that chat.
	OpenAgentSession(context.Context, *connect.Request[v1.OpenAgentSessionRequest]) (*connect.Response[v1.OpenAgentSessionResponse], error)
	// Moves a chat to another folder, or to a new worktree. A chat without
	// messages starts a new session there (and a worktree it leaves is
	// removed if it holds no work); one with messages keeps its history, in a
	// fork of its session there. Refused while the chat is busy. If the move
	// fails the chat stays where it was, with a notice saying why.
	MoveChat(context.Context, *connect.Request[v1.MoveChatRequest]) (*connect.Response[v1.MoveChatResponse], error)
	// Sends a prompt; the reply arrives as events.
	SendPrompt(context.Context, *connect.Request[v1.SendPromptRequest]) (*connect.Response[v1.SendPromptResponse], error)
	// Cuts a chat back to just before one of its user messages (when
	// status.can_rewind and the message's fork_at is set, or it is the first)
	// and returns that message. The agent's session is forked there: a new
	// session id, the same chat. Files aren't rewound. Refused while the chat
	// is busy.
	RewindChat(context.Context, *connect.Request[v1.RewindChatRequest]) (*connect.Response[v1.RewindChatResponse], error)
	// Takes a message out of the chat's queue before the agent gets it, and
	// returns it. Refused once the agent has it.
	Unqueue(context.Context, *connect.Request[v1.UnqueueRequest]) (*connect.Response[v1.UnqueueResponse], error)
	// Stops the chat's running turn (ACP session/cancel). The turn ends with a
	// "cancelled" notice, and prompts it was waiting on are cancelled. It can
	// take the last message back too (take_back).
	CancelTurn(context.Context, *connect.Request[v1.CancelTurnRequest]) (*connect.Response[v1.CancelTurnResponse], error)
	// Stops a subagent or a background command (the tool call that started
	// it), alone: through its own session when the agent shows the subagent
	// as one (Subagent.session), else by asking the agent, as a message of
	// the user's (Item.relay_stop) that waits for its next chance. It shows
	// as stopped once the agent says so.
	StopTask(context.Context, *connect.Request[v1.StopTaskRequest]) (*connect.Response[v1.StopTaskResponse], error)
	// Opens a side chat: a session the agent forks from the chat's (ACP
	// session/fork, when status.can_fork). It knows the conversation so far
	// but doesn't add to it, isn't listed or stored, and ends with
	// CloseSideChat. Its items and status come as events like any chat's.
	ForkChat(context.Context, *connect.Request[v1.ForkChatRequest]) (*connect.Response[v1.ForkChatResponse], error)
	CloseSideChat(context.Context, *connect.Request[v1.CloseSideChatRequest]) (*connect.Response[v1.CloseSideChatResponse], error)
	// Sets the chat's title; it wins over the agent's. An empty title goes
	// back to the agent's.
	RenameChat(context.Context, *connect.Request[v1.RenameChatRequest]) (*connect.Response[v1.RenameChatResponse], error)
	// Renames the branch of a chat's worktree (git branch -m; its folder
	// stays), for good: the chat's title no longer names it. Refused during a
	// turn, for a name git doesn't take or that's taken, and when the branch
	// is on a remote or another worktree or chat has it. (API 68)
	RenameBranch(context.Context, *connect.Request[v1.RenameBranchRequest]) (*connect.Response[v1.RenameBranchResponse], error)
	// Archives a chat: its turn is cancelled and its agent stops; it stays
	// listed, read-only. Unarchiving reopens it (ACP session/load).
	ArchiveChat(context.Context, *connect.Request[v1.ArchiveChatRequest]) (*connect.Response[v1.ArchiveChatResponse], error)
	// Puts a chat to sleep (when status.can_sleep): its agent stops as for
	// ArchiveChat (a running turn is stopped, side chats end), and the chat
	// stays, its transcript too. A message, or anything else that needs the
	// agent, reopens the session (ACP session/load); opening it doesn't.
	SleepChat(context.Context, *connect.Request[v1.SleepChatRequest]) (*connect.Response[v1.SleepChatResponse], error)
	// Says a chat is shown (selected, the app came to the front), or Try
	// again: a chat whose agent should run but doesn't is reopened, as
	// GetChat does, and one whose last reopen failed (status.reopen_failed)
	// tries again, once a call, unless what stopped it still holds (its
	// folder is gone, its agent isn't ready). A sleeping chat stays asleep.
	ReopenChat(context.Context, *connect.Request[v1.ReopenChatRequest]) (*connect.Response[v1.ReopenChatResponse], error)
	// The daemon's settings, and changing them.
	// Says how much memory Nushi takes, as footprint (Activity Monitor's
	// Memory), in bytes: a few milliseconds' work.
	GetMemory(context.Context, *connect.Request[v1.GetMemoryRequest]) (*connect.Response[v1.GetMemoryResponse], error)
	GetSettings(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.GetSettingsResponse], error)
	SetSettings(context.Context, *connect.Request[v1.SetSettingsRequest]) (*connect.Response[v1.SetSettingsResponse], error)
	// Nushi's copies of chats' transcripts (ADR 0047): each one's size and
	// whose it is, largest first.
	ListTranscripts(context.Context, *connect.Request[v1.ListTranscriptsRequest]) (*connect.Response[v1.ListTranscriptsResponse], error)
	// Deletes copies of transcripts: a chat goes on, its history from its
	// agent alone; one kept only for its copy (its agent deleted its
	// session) goes unless its work keeps it.
	ClearTranscripts(context.Context, *connect.Request[v1.ClearTranscriptsRequest]) (*connect.Response[v1.ClearTranscriptsResponse], error)
	// Says what DeleteChat removes. The first time, the daemon starts the
	// agent to learn whether it can delete its history.
	PlanDeleteChat(context.Context, *connect.Request[v1.PlanDeleteChatRequest]) (*connect.Response[v1.PlanDeleteChatResponse], error)
	// Deletes a chat: its turn is cancelled and its agent stops, its worktree
	// and branch go if asked, the agent deletes its history of each of the
	// chat's sessions (ACP session/delete, when it can), the chat's scratch
	// folder goes, and Nushi's record of it.
	DeleteChat(context.Context, *connect.Request[v1.DeleteChatRequest]) (*connect.Response[v1.DeleteChatResponse], error)
	// Takes chats off ListChatsResponse.removed (the app has said so).
	DismissRemovedChats(context.Context, *connect.Request[v1.DismissRemovedChatsRequest]) (*connect.Response[v1.DismissRemovedChatsResponse], error)
	// Answers a pending permission prompt with one of its options.
	AnswerPermission(context.Context, *connect.Request[v1.AnswerPermissionRequest]) (*connect.Response[v1.AnswerPermissionResponse], error)
	// Answers a pending question, or declines it.
	AnswerQuestion(context.Context, *connect.Request[v1.AnswerQuestionRequest]) (*connect.Response[v1.AnswerQuestionResponse], error)
	// Sets one of a chat's config options (mode, model, ...). Picking a mode
	// makes new chats with the same agent start in it.
	SetConfigOption(context.Context, *connect.Request[v1.SetConfigOptionRequest]) (*connect.Response[v1.SetConfigOptionResponse], error)
	// Returns a folder's uncommitted changes against HEAD, untracked files
	// included, or everything since its branch left a base, or what commits
	// changed.
	GetDiff(context.Context, *connect.Request[v1.GetDiffRequest]) (*connect.Response[v1.GetDiffResponse], error)
	// Reads one of a folder's files as it is now, as a change that changes
	// nothing (status "unchanged", the text on both sides): a file a review
	// names that isn't among the changes. Only a regular file inside the
	// folder: no "..", no link.
	GetFile(context.Context, *connect.Request[v1.GetFileRequest]) (*connect.Response[v1.GetFileResponse], error)
	// Reads a file of a chat's (in its folder or its worktree) and sends it
	// again each time it changes, until the call ends: the preview of what
	// the agent wrote. A path that leads outside them, through a link too,
	// is refused.
	WatchChatFile(context.Context, *connect.Request[v1.WatchChatFileRequest], *connect.ServerStream[v1.WatchChatFileResponse]) error
	// Lists a branch's commits since a base, or the last ones.
	ListCommits(context.Context, *connect.Request[v1.ListCommitsRequest]) (*connect.Response[v1.ListCommitsResponse], error)
	// Sums up a folder's changes (as GetDiff lists them) and names its
	// branch.
	GetFolderStatus(context.Context, *connect.Request[v1.GetFolderStatusRequest]) (*connect.Response[v1.GetFolderStatusResponse], error)
	// Lists a folder's files (up to 20,000) for @-mentions: in a git
	// repository the ones git doesn't ignore.
	ListFiles(context.Context, *connect.Request[v1.ListFilesRequest]) (*connect.Response[v1.ListFilesResponse], error)
	// Asks the chat's agent, unseen, what fills its context (Claude's
	// /context), in a throwaway fork of its session, while the chat is idle.
	// Refused when the agent can't fork.
	GetContextUsage(context.Context, *connect.Request[v1.GetContextUsageRequest]) (*connect.Response[v1.GetContextUsageResponse], error)
	// Lists the MCP servers the agent's config gives a folder, read from the
	// agent's own files, env and header values masked. With check_health, the
	// agent connects to each and says how that went (Claude's `claude mcp list`,
	// seconds), and servers only it knows (plugins', claude.ai connectors)
	// are added. Ante's (API 80): yours in $ANTE_HOME/settings.json, checked
	// by a throwaway `ante serve`; it has no off switch nor sign-in, so
	// SetMcpServerOn and Login are refused for it.
	ListMcpServers(context.Context, *connect.Request[v1.ListMcpServersRequest]) (*connect.Response[v1.ListMcpServersResponse], error)
	// Add, edit and remove an MCP server in a scope ("user", "project",
	// "local"), through the agent's own CLI; the folder names the project.
	// Editing keeps the name and scope, and env and header values sent as
	// "••••" keep the values they had; if the new config is refused, the old
	// one is put back. Running chats the change reaches get
	// status.mcp_changed.
	AddMcpServer(context.Context, *connect.Request[v1.AddMcpServerRequest]) (*connect.Response[v1.AddMcpServerResponse], error)
	EditMcpServer(context.Context, *connect.Request[v1.EditMcpServerRequest]) (*connect.Response[v1.EditMcpServerResponse], error)
	RemoveMcpServer(context.Context, *connect.Request[v1.RemoveMcpServerRequest]) (*connect.Response[v1.RemoveMcpServerResponse], error)
	// Turns a server on or off for the folder's project (API 65: by scope).
	// A project's .mcp.json server: on approves it, off rejects it (Claude's
	// enabledMcpjsonServers and disabledMcpjsonServers in the project's
	// .claude/settings.local.json). A user or local server: as /mcp in a
	// terminal does, which Claude records in ~/.claude.json, asked of Claude
	// (ADR 0050). Refused for a plugin's server and a claude.ai connector.
	SetMcpServerOn(context.Context, *connect.Request[v1.SetMcpServerOnRequest]) (*connect.Response[v1.SetMcpServerOnResponse], error)
	// Signs in to a server that needs OAuth: the agent opens the browser and
	// the call returns once the sign-in is done there, or failed (a few
	// minutes at most). Logout forgets the sign-in.
	LoginMcpServer(context.Context, *connect.Request[v1.LoginMcpServerRequest]) (*connect.Response[v1.LoginMcpServerResponse], error)
	LogoutMcpServer(context.Context, *connect.Request[v1.LogoutMcpServerRequest]) (*connect.Response[v1.LogoutMcpServerResponse], error)
	// The skills (and plugins) an agent uses in a folder (API 66, ADR 0051;
	// every agent's from API 67, ADR 0052): read from the agent's files (and
	// Claude's `claude plugin list --json`), never run in the folder; shared
	// skills (.agents/skills) with every agent that loads each. Skills'
	// descriptions and plugins' text are their authors'.
	ListSkills(context.Context, *connect.Request[v1.ListSkillsRequest]) (*connect.Response[v1.ListSkillsResponse], error)
	// Turns a skill on or off: yours in your settings, a project's in the
	// project's local settings (skillOverrides, only that key); "builtin"
	// turns Claude's built-in skills on or off together, in your settings
	// (disableBundledSkills). A plugin's skills go with their plugin.
	SetSkillOn(context.Context, *connect.Request[v1.SetSkillOnRequest]) (*connect.Response[v1.SetSkillOnResponse], error)
	// Turns an installed plugin on or off where Plugin.switch_scope says:
	// for you through `claude plugin enable`/`disable` (run in Claude's config
	// folder, never the project's), for the project by its enabledPlugins
	// entry in the project's local settings.
	SetPluginOn(context.Context, *connect.Request[v1.SetPluginOnRequest]) (*connect.Response[v1.SetPluginOnResponse], error)
	// Uninstalls a plugin installed for you (`claude plugin uninstall`);
	// refused for one installed for a project.
	UninstallPlugin(context.Context, *connect.Request[v1.UninstallPluginRequest]) (*connect.Response[v1.UninstallPluginResponse], error)
	// Moves a skill's folder (yours or the project's, as listed) to the
	// Trash.
	TrashSkill(context.Context, *connect.Request[v1.TrashSkillRequest]) (*connect.Response[v1.TrashSkillResponse], error)
	// Gives an agent a shared skill it doesn't read by a relative link of
	// its own (Claude's .claude/skills/<name> → ../../.agents/skills/<name>):
	// only a shared skill listed for the folder; nothing replaced.
	LinkSkill(context.Context, *connect.Request[v1.LinkSkillRequest]) (*connect.Response[v1.LinkSkillResponse], error)
	// Reopens a chat's session on a new agent (ACP session/load), which
	// replays its transcript, so it uses the MCP servers as they are now.
	// Refused while it is busy.
	ReloadChat(context.Context, *connect.Request[v1.ReloadChatRequest]) (*connect.Response[v1.ReloadChatResponse], error)
	// Opens a terminal for a chat: the user's login shell, in the chat's
	// folder (its worktree, for a worktree chat) or in a given one. The
	// daemon owns it, so it outlives the app, but not the daemon. Changes to
	// a chat's terminals come as events.
	OpenTerminal(context.Context, *connect.Request[v1.OpenTerminalRequest]) (*connect.Response[v1.OpenTerminalResponse], error)
	ListTerminals(context.Context, *connect.Request[v1.ListTerminalsRequest]) (*connect.Response[v1.ListTerminalsResponse], error)
	// Streams a terminal's output: first what it kept (the last 1 MB, maybe
	// empty), then new output, and a last message once its shell has exited.
	// A client that falls far behind is cut off and attaches again.
	AttachTerminal(context.Context, *connect.Request[v1.AttachTerminalRequest], *connect.ServerStream[v1.AttachTerminalResponse]) error
	WriteTerminal(context.Context, *connect.Request[v1.WriteTerminalRequest]) (*connect.Response[v1.WriteTerminalResponse], error)
	ResizeTerminal(context.Context, *connect.Request[v1.ResizeTerminalRequest]) (*connect.Response[v1.ResizeTerminalResponse], error)
	// Names a terminal; an empty name goes back to the one it shows by
	// itself.
	RenameTerminal(context.Context, *connect.Request[v1.RenameTerminalRequest]) (*connect.Response[v1.RenameTerminalResponse], error)
	// Puts a chat's terminals in an order.
	ArrangeTerminals(context.Context, *connect.Request[v1.ArrangeTerminalsRequest]) (*connect.Response[v1.ArrangeTerminalsResponse], error)
	// Starts a new shell in a terminal's folder in place of its old one (a
	// shell that exited), keeping its place and name.
	RestartTerminal(context.Context, *connect.Request[v1.RestartTerminalRequest]) (*connect.Response[v1.RestartTerminalResponse], error)
	// Closes a terminal: its shell is hung up, then killed after a short
	// grace, along with what still runs in it.
	CloseTerminal(context.Context, *connect.Request[v1.CloseTerminalRequest]) (*connect.Response[v1.CloseTerminalResponse], error)
	// Says what a folder brings for the agent to run on its own (MCP
	// servers, hooks, helper commands) when neither the agent nor Nushi was
	// told to trust it; nothing when it is trusted or brings nothing. Ask
	// before starting or moving a chat there.
	CheckFolder(context.Context, *connect.Request[v1.CheckFolderRequest]) (*connect.Response[v1.CheckFolderResponse], error)
	// Remembers that the user starts chats in a folder anyway (its
	// repository, outside git the folders under it too).
	TrustFolder(context.Context, *connect.Request[v1.TrustFolderRequest]) (*connect.Response[v1.TrustFolderResponse], error)
	// Remote access (ADRs 0033, 0034): how it stands, and switching it on
	// or off through a relay.
	GetRemote(context.Context, *connect.Request[v1.GetRemoteRequest]) (*connect.Response[v1.GetRemoteResponse], error)
	SetRemote(context.Context, *connect.Request[v1.SetRemoteRequest]) (*connect.Response[v1.SetRemoteResponse], error)
	// Starts pairing a phone (remote access must be on): the text for the QR
	// code, good until it expires. Once a phone holding it connects,
	// Remote.pairing has its name and the code both screens show.
	StartPairing(context.Context, *connect.Request[v1.StartPairingRequest]) (*connect.Response[v1.StartPairingResponse], error)
	// Allows or denies the phone that connected, named by its code.
	ConfirmPairing(context.Context, *connect.Request[v1.ConfirmPairingRequest]) (*connect.Response[v1.ConfirmPairingResponse], error)
	// Unpairs a phone and drops its connections.
	RevokeDevice(context.Context, *connect.Request[v1.RevokeDeviceRequest]) (*connect.Response[v1.RevokeDeviceResponse], error)
	// Web Push (ADR 0054). The daemon's VAPID public key, for a device's
	// pushManager.subscribe.
	GetPushKey(context.Context, *connect.Request[v1.GetPushKeyRequest]) (*connect.Response[v1.GetPushKeyResponse], error)
	// A paired device's own push subscription (an empty endpoint: none);
	// only on a device's channel. The endpoint must be a known push service.
	SetPushSubscription(context.Context, *connect.Request[v1.SetPushSubscriptionRequest]) (*connect.Response[v1.SetPushSubscriptionResponse], error)
	// The chat a client shows ("" none), said again within 40 s while it
	// does: that chat is seen (Chat.unseen), and no push for it goes to the
	// device while it's connected. On the Mac's socket it's the Mac's window
	// (API 76; before, only on a device's channel).
	SetDeviceView(context.Context, *connect.Request[v1.SetDeviceViewRequest]) (*connect.Response[v1.SetDeviceViewResponse], error)
	// Sends a test notification to a device (the Mac's).
	SendTestPush(context.Context, *connect.Request[v1.SendTestPushRequest]) (*connect.Response[v1.SendTestPushResponse], error)
	// Unpairs the device that calls (its Forget this Mac), as Revoke would;
	// only on a device's channel.
	UnpairThisDevice(context.Context, *connect.Request[v1.UnpairThisDeviceRequest]) (*connect.Response[v1.UnpairThisDeviceResponse], error)
	// Writes a line of the app's into the daemon's log (source=app): its
	// errors with their stacks, and what helps afterwards.
	Log(context.Context, *connect.Request[v1.LogRequest]) (*connect.Response[v1.LogResponse], error)
	// Jira (ADR 0042): the sites added, their tokens in the keychain. Every
	// call that reaches Jira is one the user made; nothing polls or writes on
	// its own.
	ListJiraSites(context.Context, *connect.Request[v1.ListJiraSitesRequest]) (*connect.Response[v1.ListJiraSitesResponse], error)
	// Checks a token on a site (classic or scoped) and keeps it: the token
	// in the keychain, the site in the list.
	AddJiraSite(context.Context, *connect.Request[v1.AddJiraSiteRequest]) (*connect.Response[v1.AddJiraSiteResponse], error)
	// Forgets a site and deletes its token from the keychain.
	RemoveJiraSite(context.Context, *connect.Request[v1.RemoveJiraSiteRequest]) (*connect.Response[v1.RemoveJiraSiteResponse], error)
	// Asks Jira who a site's token is, to see it still works.
	CheckJiraSite(context.Context, *connect.Request[v1.CheckJiraSiteRequest]) (*connect.Response[v1.CheckJiraSiteResponse], error)
	// Reads a site's token with macOS's prompt, which asks to let this
	// build of Nushi read it (JiraSite.needs_ok).
	AllowJiraToken(context.Context, *connect.Request[v1.AllowJiraTokenRequest]) (*connect.Response[v1.AllowJiraTokenResponse], error)
	// The board whose active sprint is the sprint list, and saved searches.
	ListJiraBoards(context.Context, *connect.Request[v1.ListJiraBoardsRequest]) (*connect.Response[v1.ListJiraBoardsResponse], error)
	SetJiraBoard(context.Context, *connect.Request[v1.SetJiraBoardRequest]) (*connect.Response[v1.SetJiraBoardResponse], error)
	SetJiraSearches(context.Context, *connect.Request[v1.SetJiraSearchesRequest]) (*connect.Response[v1.SetJiraSearchesResponse], error)
	// A list's issues: "mine", "sprint", or a JQL search.
	ListJiraIssues(context.Context, *connect.Request[v1.ListJiraIssuesRequest]) (*connect.Response[v1.ListJiraIssuesResponse], error)
	// What the JQL field autocompletes from, and a field's values.
	GetJiraJql(context.Context, *connect.Request[v1.GetJiraJqlRequest]) (*connect.Response[v1.GetJiraJqlResponse], error)
	SuggestJiraJql(context.Context, *connect.Request[v1.SuggestJiraJqlRequest]) (*connect.Response[v1.SuggestJiraJqlResponse], error)
	// An issue whole, text as Markdown.
	GetJiraIssue(context.Context, *connect.Request[v1.GetJiraIssueRequest]) (*connect.Response[v1.GetJiraIssueResponse], error)
	ListJiraTransitions(context.Context, *connect.Request[v1.ListJiraTransitionsRequest]) (*connect.Response[v1.ListJiraTransitionsResponse], error)
	TransitionJiraIssue(context.Context, *connect.Request[v1.TransitionJiraIssueRequest]) (*connect.Response[v1.TransitionJiraIssueResponse], error)
	// Posts a comment written in Markdown.
	AddJiraComment(context.Context, *connect.Request[v1.AddJiraCommentRequest]) (*connect.Response[v1.AddJiraCommentResponse], error)
	// An issue for a new chat: from its link, its key, or words of it.
	FindJiraIssues(context.Context, *connect.Request[v1.FindJiraIssuesRequest]) (*connect.Response[v1.FindJiraIssuesResponse], error)
	// An attachment's file or thumbnail (20 MB at most).
	GetJiraAttachment(context.Context, *connect.Request[v1.GetJiraAttachmentRequest]) (*connect.Response[v1.GetJiraAttachmentResponse], error)
	// GitHub (ADR 0045): the hosts gh is signed in to (its token read by the
	// daemon through go-gh) and those given a pasted token (the keychain).
	// Nothing reaches GitHub on its own: the app asks, and marks the asking
	// on its timers quiet, which a rate limit running low holds back.
	ListGitHubHosts(context.Context, *connect.Request[v1.ListGitHubHostsRequest]) (*connect.Response[v1.ListGitHubHostsResponse], error)
	// Checks a pasted token on a host and keeps it in the keychain; it's
	// used for the host instead of gh's login until removed.
	AddGitHubToken(context.Context, *connect.Request[v1.AddGitHubTokenRequest]) (*connect.Response[v1.AddGitHubTokenResponse], error)
	RemoveGitHubToken(context.Context, *connect.Request[v1.RemoveGitHubTokenRequest]) (*connect.Response[v1.RemoveGitHubTokenResponse], error)
	// Reads a host's pasted token with macOS's prompt (GitHubHost.needs_ok).
	AllowGitHubToken(context.Context, *connect.Request[v1.AllowGitHubTokenRequest]) (*connect.Response[v1.AllowGitHubTokenResponse], error)
	// The GitHub repositories folders are clones of: the folders asked
	// about and the chats'.
	ListGitHubRepos(context.Context, *connect.Request[v1.ListGitHubReposRequest]) (*connect.Response[v1.ListGitHubReposResponse], error)
	// Review requested of me or my teams, my pull requests, issues assigned
	// to me: the latest 50 each.
	ListGitHubInbox(context.Context, *connect.Request[v1.ListGitHubInboxRequest]) (*connect.Response[v1.ListGitHubInboxResponse], error)
	// Items as they are now, by node id (a chat's status chip).
	GetGitHubStates(context.Context, *connect.Request[v1.GetGitHubStatesRequest]) (*connect.Response[v1.GetGitHubStatesResponse], error)
	GetGitHubPull(context.Context, *connect.Request[v1.GetGitHubPullRequest]) (*connect.Response[v1.GetGitHubPullResponse], error)
	GetGitHubIssue(context.Context, *connect.Request[v1.GetGitHubIssueRequest]) (*connect.Response[v1.GetGitHubIssueResponse], error)
	// A pull request's files from its merge base to its head, both sides'
	// texts, as GetDiff gives them.
	GetGitHubFiles(context.Context, *connect.Request[v1.GetGitHubFilesRequest]) (*connect.Response[v1.GetGitHubFilesResponse], error)
	// The end of a failed Actions job's log (16 KB).
	GetGitHubJobLog(context.Context, *connect.Request[v1.GetGitHubJobLogRequest]) (*connect.Response[v1.GetGitHubJobLogResponse], error)
	// A message for a chat's agent, for the box (never sent by Nushi):
	// "fix_checks" (the failed checks with their logs' ends) or
	// "address_comments" (the threads named, else all not resolved), GitHub's
	// text in it marked as data.
	GetGitHubPrompt(context.Context, *connect.Request[v1.GetGitHubPromptRequest]) (*connect.Response[v1.GetGitHubPromptResponse], error)
	// The user's writes.
	ReplyGitHubThread(context.Context, *connect.Request[v1.ReplyGitHubThreadRequest]) (*connect.Response[v1.ReplyGitHubThreadResponse], error)
	ResolveGitHubThread(context.Context, *connect.Request[v1.ResolveGitHubThreadRequest]) (*connect.Response[v1.ResolveGitHubThreadResponse], error)
	AddGitHubComment(context.Context, *connect.Request[v1.AddGitHubCommentRequest]) (*connect.Response[v1.AddGitHubCommentResponse], error)
	SubmitGitHubReview(context.Context, *connect.Request[v1.SubmitGitHubReviewRequest]) (*connect.Response[v1.SubmitGitHubReviewResponse], error)
	// A chat's pull request: the one it was started from, else the one whose
	// head is its folder's branch, looked for on GitHub (and linked when
	// found), with the folder's repository and branch. API 81.
	FindChatPull(context.Context, *connect.Request[v1.FindChatPullRequest]) (*connect.Response[v1.FindChatPullResponse], error)
	// Links a pull request picked by hand to a chat, or unlinks its own.
	// API 81.
	LinkChatPull(context.Context, *connect.Request[v1.LinkChatPullRequest]) (*connect.Response[v1.LinkChatPullResponse], error)
	// Streams every change to every chat from now on. The first message is
	// empty: it says the subscription is live.
	Events(context.Context, *connect.Request[v1.EventsRequest], *connect.ServerStream[v1.EventsResponse]) error
}

